arguments.command:
python3 -c "
import json
rows=[json.loads(l) for l in open('metrics.jsonl')]
for r in rows:
    d=r['data']
    if r['step'] in (1,10,20,40,60,80,100):
        sel={k:round(d[k],4) for k in ['critic/score/mean','critic/rewards/mean','actor/grad_norm','actor/entropy','actor/ppo_kl','actor/kl_loss','response_length/clip_ratio','response/aborted_ratio','actor/pg_clipfrac'] if k in d}
        print(r['step'], sel)
"

